<template>
  <section ref="editorRoot" class="graph-editor" tabindex="0" @keydown="onKeydown">
    <header class="graph-toolbar">
      <div class="primary-actions">
        <button class="primary" @click="createGraph">＋ {{ t('newVisualGraph') }}</button>
        <button :disabled="!activeAsset || !dirty" @click="saveGraph">{{ t('saveAsset') }}</button>
        <button :disabled="!canUndo" :title="t('undo')" @click="undo">↶</button><button :disabled="!canRedo" :title="t('redo')" @click="redo">↷</button>
      </div>
      <select v-model="activeScopeUuid" class="scope-picker" :title="t('graphScope')" @change="scopeChanged">
        <option value="main">{{ t('mainGraph') }}</option>
        <option v-for="routine in graph.routines" :key="routine.uuid" :value="routine.uuid">{{ routine.kind }} · {{ routine.name }}</option>
      </select>
      <div class="authoring-switch" role="group" :aria-label="t('visualAuthoringStyle')"><button :class="{ active: studio.authoringMode === 'blocks' }" @click="setAuthoringMode('blocks')">▰ {{ t('blockMode') }}</button><button :class="{ active: studio.authoringMode === 'nodes' }" @click="setAuthoringMode('nodes')">⌘ {{ t('nodeMode') }}</button></div>
      <div class="editing-actions">
        <button :class="{ active: studio.paletteOpen }" @click="togglePalette">＋ {{ t('nodePalette') }}</button>
        <button :disabled="!selectedNodes.size" @click="duplicateSelected">{{ t('duplicate') }}</button>
        <button :disabled="selectedNodes.size < 2" @click="alignSelected">{{ t('alignLeft') }}</button>
        <button :disabled="selectedNodes.size < 3" @click="distributeSelected">{{ t('distributeHorizontal') }}</button>
        <button @click="addComment">{{ t('graphComment') }}</button>
        <button @click="() => arrangeScratchBlocks()">{{ t('tidyBlocks') }}</button>
        <button @click="() => frameAll()">{{ t('frameAll') }}</button>
      </div>
      <span class="graph-status" :class="{ invalid: !validation.valid }">{{ validation.valid ? t('graphReady') : t('graphErrors', { count: errorCount }) }} · {{ activeScope.nodes.length }} {{ t('nodes') }} · {{ validation.elapsedMs.toFixed(1) }} ms</span>
    </header>

    <div ref="graphBody" class="graph-body" :class="{ 'no-palette': !studio.paletteOpen, 'no-details': !studio.detailsOpen, 'blocks-mode': studio.authoringMode === 'blocks' }">
      <aside v-if="studio.paletteOpen" class="graph-palette">
        <header><strong>{{ t('nodePalette') }}</strong><button :title="t('close')" @click="closePalette">×</button></header>
        <nav v-if="studio.authoringMode === 'blocks'" class="block-categories" :aria-label="t('blockCategories')"><button v-for="family in scratchFamilies" :key="family.id" :class="{ active: blockFamily === family.id }" :style="{ '--family-color': family.color }" @click="blockFamily = family.id"><i></i><span>{{ t(family.label) }}</span></button></nav>
        <input ref="paletteInput" v-model="paletteSearch" type="search" :placeholder="t('searchNodes')" @keydown.enter.prevent="addFirstPaletteNode">
        <div class="asset-list">
          <button v-for="asset in graphAssets" :key="asset.uuid" :class="{ active: asset.uuid === activeAsset?.uuid }" @click="openGraph(asset.uuid)"><i>⌘</i><span><strong>{{ asset.name }}</strong><small>{{ asset.path }}</small></span></button>
        </div>
        <div class="palette-list">
          <section v-for="group in paletteGroups" :key="group.category"><h3>{{ localizedCategory(group.category) }}</h3><button v-for="definition in group.items" :key="definition.type" :title="definition.description" :style="{ '--family-color': familyColor[scratchFamily(definition.category)] }" @click="addNode(definition.type)"><i :style="{ background: studio.authoringMode === 'blocks' ? familyColor[scratchFamily(definition.category)] : definition.color }"></i><span><strong>{{ definition.title }}</strong><small>{{ definition.description }}</small></span></button></section>
          <p v-if="!paletteResults.length" class="empty">{{ t('noMatchingNodes') }}</p>
        </div>
      </aside>

      <main ref="canvas" class="graph-canvas" :class="{ connecting: pendingWire, 'graph-low-detail': lowDetail, 'is-panning': isPanning }" @pointerdown.capture="canvasPointerDownCapture" @pointerdown="canvasPointerDown" @dblclick.self="openPaletteAtPointer" @wheel.capture.prevent.stop="zoomCanvas">
        <div class="graph-grid" :style="gridStyle"></div>
        <svg class="graph-transform wires" :style="transformStyle" aria-hidden="true">
          <path v-for="edge in visibleEdges" :key="edge.uuid" :d="edgePath(edge)" :class="[edgeKind(edge), { active: graphDebugState.activeEdgeUuid === edge.uuid }]" />
          <path v-if="pendingWire && pointerGraph" :d="pendingPath" class="pending" />
        </svg>
        <div class="graph-transform comments" :style="transformStyle">
          <article v-for="comment in activeScope.comments" :key="comment.uuid" class="graph-comment" :class="{ collapsed: comment.collapsed }" :style="commentStyle(comment)" @pointerdown.stop="startCommentDrag($event, comment)"><header :style="{ borderColor: comment.color }"><input v-model="comment.text" maxlength="2048" @change="markDirty"><button @click.stop="comment.collapsed = !comment.collapsed; markDirty()">{{ comment.collapsed ? '+' : '−' }}</button></header></article>
        </div>
        <div class="graph-transform nodes-layer" :style="transformStyle">
          <article v-for="node in visibleNodes" :key="node.uuid" class="graph-node" :class="[blockKind(node), `family-${scratchFamilyForNode(node)}`, { selected: selectedNodes.has(node.uuid), collapsed: node.collapsed, breakpoint: hasBreakpoint(node.uuid), executing: graphDebugState.activeNodeUuid === node.uuid, failed: hasNodeError(node.uuid), covered: graphDebugState.coverage[node.uuid] > 0 }]" :style="nodeStyle(node)" @pointerdown.stop="selectNode($event,node)">
            <header :style="{ '--node-color': nodeColor(node) }" @pointerdown.stop="startNodeDrag($event,node)"><button class="breakpoint-toggle" :title="t('toggleBreakpoint')" @pointerdown.stop @click.stop="toggleBreakpoint(node.uuid)"></button><i></i><strong>{{ node.title }}</strong><small>{{ node.category }}</small><button :title="t('collapse')" @pointerdown.stop @click.stop="node.collapsed = !node.collapsed; markDirty()">{{ node.collapsed ? '+' : '−' }}</button></header>
            <div v-if="!node.collapsed" class="node-pins">
              <div v-for="pin in node.pins" :key="pin.uuid" class="node-pin" :class="[pin.direction,pin.kind]">
                <button class="pin-dot" :class="[pin.valueType?.toLowerCase(), { compatible: compatiblePin(pin) }]" :title="`${pin.name} · ${pin.kind === 'execution' ? t('executionPin') : pin.valueType}`" @pointerdown.stop.prevent="startWire($event,node,pin)" @pointerup.stop="finishWire(node,pin)" @click.stop="pinClicked(node,pin)"></button>
                <span>{{ pin.name }}</span>
                <template v-if="pin.kind === 'data' && pin.direction === 'input' && !pinConnected(pin)">
                  <input v-if="pin.valueType === 'Number'" :value="pin.defaultValue" type="number" step="0.01" @input="updatePinNumber(pin,$event)" @change="setPinNumber(pin,$event)">
                  <input v-else-if="pin.valueType === 'Boolean'" :checked="pin.defaultValue === true" type="checkbox" @change="pin.defaultValue = ($event.target as HTMLInputElement).checked; markDirty()">
                  <div v-else-if="pin.valueType === 'Vec2'" class="vec-input"><input :value="vecPart(pin.defaultValue,0)" type="number" step="0.01" @input="updatePinVector(pin,0,$event)" @change="setPinVector(pin,0,$event)"><input :value="vecPart(pin.defaultValue,1)" type="number" step="0.01" @input="updatePinVector(pin,1,$event)" @change="setPinVector(pin,1,$event)"></div>
                  <input v-else :value="displayPinValue(pin.defaultValue)" type="text" @input="updatePinText(pin,$event)" @change="setPinText(pin,$event)">
                </template>
                <template v-if="node.type.startsWith('literal.') && pin.direction === 'output'">
                  <input v-if="pin.valueType === 'Number'" :value="node.config.value" type="number" step="0.01" @input="updateLiteralNumber(node,$event)" @change="setLiteralNumber(node,$event)">
                  <input v-else-if="pin.valueType === 'Boolean'" :checked="node.config.value === true" type="checkbox" @change="node.config.value = ($event.target as HTMLInputElement).checked; markDirty()">
                  <div v-else-if="pin.valueType === 'Vec2'" class="vec-input"><input :value="vecPart(node.config.value,0)" type="number" step="0.01" @input="updateLiteralVector(node,0,$event)" @change="setLiteralVector(node,0,$event)"><input :value="vecPart(node.config.value,1)" type="number" step="0.01" @input="updateLiteralVector(node,1,$event)" @change="setLiteralVector(node,1,$event)"></div>
                  <input v-else :value="displayPinValue(node.config.value)" type="text" @input="updateLiteralText(node,$event)" @change="setLiteralText(node,$event)">
                </template>
              </div>
            </div>
            <select v-if="node.type.startsWith('variable.') && !node.collapsed" :value="node.config.variableUuid" @change="selectNodeVariable(node,$event)"><option value="">{{ t('selectVariable') }}</option><option v-for="variable in graph.variables" :key="variable.uuid" :value="variable.uuid">{{ variable.name }} · {{ variable.valueType }}</option></select>
            <select v-if="node.type.startsWith('local.') && activeRoutine && !node.collapsed" :value="node.config.localUuid" @change="selectNodeLocal(node,$event)"><option value="">{{ t('selectLocal') }}</option><option v-for="local in activeRoutine.locals" :key="local.uuid" :value="local.uuid">{{ local.name }} · {{ local.valueType }}</option></select>
            <section v-if="!node.collapsed && (node.type.startsWith('code.') || typeof node.config.rhaiSourceOverride === 'string')" class="node-source" @pointerdown.stop>
              <span>{{ node.config.rhaiSourceOverride ? t('linkedCodeOverride') : t('generatedRhai') }}</span>
              <textarea :value="nodeCodeSource(node)" spellcheck="false" @input="updateNodeCodeSource(node,$event)" @change="setNodeCodeSource(node,$event)"></textarea>
              <button v-if="node.config.rhaiSourceOverride" @click="clearNodeCodeOverride(node)">{{ t('clearCodeOverride') }}</button>
            </section>
            <div v-if="!node.collapsed && nodeLiveValues(node).length" class="node-live-values" aria-live="polite"><span v-for="item in nodeLiveValues(node)" :key="item[0]"><b>{{ item[0] }}</b><code>{{ item[1] }}</code></span></div>
          </article>
        </div>
        <div v-if="selectionBox" class="selection-box" :style="selectionBoxStyle"></div>
        <div class="canvas-controls" role="toolbar" :aria-label="t('graphNavigation')" @pointerdown.stop><button type="button" :aria-label="t('zoomOut')" :title="t('zoomOut')" @click.stop="changeZoom(-.1)">−</button><input :aria-label="t('graphZoom')" :aria-valuetext="`${Math.round(activeScope.viewport.zoom * 100)}%`" :value="activeScope.viewport.zoom" type="range" min="0.1" max="4" step="0.05" @input="zoomSlider"><button type="button" class="zoom-value" :aria-label="t('resetZoom')" :title="t('resetZoom')" @click.stop="resetZoom">{{ Math.round(activeScope.viewport.zoom * 100) }}%</button><button type="button" :aria-label="t('zoomIn')" :title="t('zoomIn')" @click.stop="changeZoom(.1)">＋</button><button type="button" :aria-label="t('frameAll')" :title="t('frameAll')" @click.stop="frameAll()">⌗</button><button type="button" :aria-label="t('minimap')" :title="t('minimap')" :class="{ active: studio.minimapOpen }" @click.stop="studio.minimapOpen = !studio.minimapOpen">▣</button></div>
        <div class="graph-hint" aria-live="polite"><span>{{ t('graphPanHint') }}</span><span>·</span><span>{{ t('graphConnectHint') }}</span><span>·</span><span>{{ t('graphAddHint') }}</span></div>
        <aside v-if="studio.minimapOpen" class="minimap" @pointerdown.stop><header>{{ t('minimap') }}</header><svg viewBox="0 0 200 120" @pointerdown.stop.prevent="navigateMinimap"><rect v-for="node in activeScope.nodes" :key="node.uuid" :x="miniX(node.position.x)" :y="miniY(node.position.y)" width="8" height="5" :class="{ selected: selectedNodes.has(node.uuid) }" /><rect class="viewport" v-bind="miniViewport" /></svg></aside>
        <button v-if="!studio.paletteOpen" type="button" class="open-palette" @pointerdown.stop @click.stop="openPalette">＋ {{ t('nodes') }}</button>
      </main>

      <aside v-if="studio.detailsOpen" class="graph-details">
        <header><strong>{{ t('graphDetails') }}</strong><button :title="t('close')" @click="closeDetails">×</button></header>
        <section class="graph-summary"><label><span>{{ t('graphName') }}</span><input v-model="graph.name" maxlength="120" @change="markDirty"></label><div><span>Format {{ graph.version }}</span><span>Rhai API {{ graph.apiVersion }}</span></div></section>
        <GraphProductionPanel :graph="graph" :scope-uuid="activeScopeUuid" :selected-node-uuids="[...selectedNodes]" :compiled-source="compileResult.source" @dirty="markDirty" @scope="setActiveScope" @replace-graph="replaceGraph" />
        <section class="variables"><header><strong>{{ t('graphVariables') }}</strong><button @click="addVariable">＋</button></header><article v-for="variable in graph.variables" :key="variable.uuid"><div><input v-model="variable.name" maxlength="80" @change="normalizeVariable(variable)"><select v-model="variable.valueType" @change="variableTypeChanged(variable)"><option v-for="type in valueTypes" :key="type">{{ type }}</option></select><button class="danger" @click="removeVariable(variable.uuid)">×</button></div><label><input v-model="variable.exposed" type="checkbox" @change="markDirty"><span>{{ t('exposeInInspector') }}</span></label><input v-model="variable.group" :placeholder="t('group')" maxlength="80" @change="markDirty"><input v-model="variable.tooltip" :placeholder="t('tooltip')" maxlength="512" @change="markDirty"><div v-if="variable.valueType === 'Number'" class="number-metadata"><input v-model.number="variable.minimum" type="number" :placeholder="t('minimum')" @change="markDirty"><input v-model.number="variable.maximum" type="number" :placeholder="t('maximum')" @change="markDirty"><input v-model.number="variable.step" type="number" min="0.000001" :placeholder="t('step')" @change="markDirty"></div><input :value="displayPinValue(variable.defaultValue)" :placeholder="t('defaultValue')" @change="setVariableDefault(variable,$event)"></article><p v-if="!graph.variables.length">{{ t('noGraphVariables') }}</p></section>
        <section class="diagnostics"><header><strong>{{ t('validation') }}</strong><button @click="showCompiled = !showCompiled">{{ showCompiled ? t('problems') : t('generatedRhai') }}</button></header><template v-if="!showCompiled"><button v-for="diagnostic in validation.diagnostics" :key="`${diagnostic.code}:${diagnostic.nodeUuid}:${diagnostic.pinUuid}`" :class="diagnostic.severity" @click="focusDiagnostic(diagnostic)"><i></i><span><strong>{{ diagnostic.code }}</strong><small>{{ diagnostic.message }}</small></span></button><p v-if="!validation.diagnostics.length" class="valid">✓ {{ t('graphValidationPassed') }}</p></template><pre v-else>{{ compileResult.source || t('graphCannotCompile') }}</pre></section>
      </aside>
      <button v-if="!studio.detailsOpen" class="open-details" @click="openDetails">{{ t('graphDetails') }} ‹</button>
    </div>
  </section>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, shallowRef, triggerRef, watch } from 'vue'
import { assetState, createTextAsset, readTextAsset, updateTextAsset } from '../assets/AssetDatabase'
import { addEditorLog } from '../store/editor'
import { pushHistory } from '../store/physics'
import { t } from '../i18n'
import { createGraphNode, defaultVisualGraph, graphNodeDefinition, searchGraphNodeCatalog, type GraphNodeDefinition } from '../visual/graphCatalog'
import { compileGraph, type GraphDiagnostic } from '../visual/graphCompiler'
import { graphStudioState as studio, openGraphAsset } from '../visual/graphStudioState'
import { defaultGraphValue, graphUuid, parseGraphDocument, serializeGraphDocument, type GraphCanvasScope, type GraphComment, type GraphEdge, type GraphNode, type GraphPin, type GraphValue, type GraphValueType, type GraphVariable, type NovaGraphDocument } from '../visual/graphTypes'
import { graphDebugState } from '../visual/graphDebugger'
import { ensureLinkedScriptForGraph, synchronizeLinkedScriptsForGraph } from '../visual/graphCodeSync'
import GraphProductionPanel from './GraphProductionPanel.vue'
import { gameplayRuntime } from '../runtime/GameplayRuntime'
import { arrangeExecutionBlocks, availableGraphPosition, dragGraphPoint, focalGraphZoom, graphNodeLayoutSize, panGraphViewport, stepGraphZoom, useLowDetailGraph, wheelGraphZoom } from '../visual/graphInteraction'

const editorRoot = ref<HTMLElement | null>(null), graphBody = ref<HTMLElement | null>(null), canvas = ref<HTMLElement | null>(null), paletteInput = ref<HTMLInputElement | null>(null)
const graph = shallowRef<NovaGraphDocument>(defaultVisualGraph()), dirty = ref(false), loadedAssetUuid = ref(''), paletteSearch = ref(''), showCompiled = ref(false), blockFamily = ref('Events')
const activeScopeUuid = ref('main')
const selectedNodes = reactive(new Set<string>()), pendingWire = shallowRef<{ node: GraphNode; pin: GraphPin } | null>(null), pointerGraph = shallowRef<{ x: number; y: number } | null>(null)
const history = ref<string[]>([]), historyIndex = ref(-1), restoring = ref(false), canvasSize = reactive({ width: 900, height: 600 })
const selectionBox = ref<{ startX: number; startY: number; x: number; y: number; width: number; height: number } | null>(null)
const paletteAnchor = ref<{ x: number; y: number } | null>(null), isPanning = ref(false), compactLayout = ref(false)
let resizeObserver: ResizeObserver | null = null, compileTimer: number | undefined, viewportHistoryTimer: number | undefined, visualFrame = 0, pointerFrame = 0, queuedVisualUpdate: (() => void) | null = null, queuedPointerEvent: PointerEvent | null = null

const graphAssets = computed(() => { void assetState.generation; return assetState.records.filter(asset => asset.assetType === 'visualScript').sort((a,b) => a.path.localeCompare(b.path)) })
const activeAsset = computed(() => graphAssets.value.find(asset => asset.uuid === (loadedAssetUuid.value || studio.activeGraphUuid)) ?? null)
const activeRoutine = computed(() => graph.value.routines.find(routine => routine.uuid === activeScopeUuid.value) ?? null)
const activeScope = computed<GraphCanvasScope>(() => activeRoutine.value ?? graph.value)
const compileResult = shallowRef(compileGraph(graph.value)), validation = computed(() => compileResult.value), errorCount = computed(() => validation.value.diagnostics.filter(item => item.severity === 'error').length)
const canUndo = computed(() => historyIndex.value > 0), canRedo = computed(() => historyIndex.value >= 0 && historyIndex.value < history.value.length - 1)
const valueTypes: GraphValueType[] = ['Boolean','Number','String','Vec2','Entity','Resource','Data']
const scratchFamilies = [
  {id:'Motion',label:'blockMotion',color:'#4c97ff'},{id:'Looks',label:'blockLooks',color:'#9966ff'},{id:'Sound',label:'blockSound',color:'#cf63cf'},
  {id:'Events',label:'blockEvents',color:'#ffbf00'},{id:'Control',label:'blockControl',color:'#ffab19'},{id:'Sensing',label:'blockSensing',color:'#5cb1d6'},
  {id:'Operators',label:'blockOperators',color:'#59c059'},{id:'Variables',label:'blockVariables',color:'#ff8c1a'},{id:'MyBlocks',label:'blockMyBlocks',color:'#ff6680'},{id:'Extensions',label:'blockExtensions',color:'#0fbd8c'}
] as const
const familyColor = Object.fromEntries(scratchFamilies.map(item=>[item.id,item.color])) as Record<string,string>
function scratchFamily(category:string):string { if(category==='Transform')return'Motion';if(['UI','Animation','Scene'].includes(category))return'Looks';if(category==='Audio')return'Sound';if(['Events','Signals'].includes(category))return'Events';if(['Flow','Timing'].includes(category))return'Control';if(['Input','Physics','Gameplay'].includes(category))return'Sensing';if(['Math','Comparison','Conversion','Values'].includes(category))return'Operators';if(['Variables','Save'].includes(category))return'Variables';if(category==='Functions')return'MyBlocks';return'Extensions' }
function scratchFamilyForNode(node:GraphNode){return scratchFamily(node.category)}
const paletteResults = computed(() => searchGraphNodeCatalog(paletteSearch.value, graph.value, activeRoutine.value).filter(item=>studio.authoringMode!=='blocks'||paletteSearch.value.trim()||scratchFamily(item.category)===blockFamily.value).slice(0,240))
const paletteGroups = computed(() => { const groups = new Map<string, GraphNodeDefinition[]>(); for (const item of paletteResults.value) groups.set(item.category, [...(groups.get(item.category) ?? []), item]); return [...groups].map(([category,items]) => ({category,items})) })
const transformStyle = computed(() => { void graph.value; return { transform: `translate(${activeScope.value.viewport.x}px,${activeScope.value.viewport.y}px) scale(${activeScope.value.viewport.zoom})` } })
const gridStyle = computed(() => { void graph.value; const size = 24 * activeScope.value.viewport.zoom; return { backgroundSize: `${size}px ${size}px`, backgroundPosition: `${activeScope.value.viewport.x % size}px ${activeScope.value.viewport.y % size}px` } })
const visibleNodes = computed(() => { void graph.value; if (activeScope.value.nodes.length <= 300) return activeScope.value.nodes; const z = activeScope.value.viewport.zoom, margin = 400, left = -activeScope.value.viewport.x / z - margin, top = -activeScope.value.viewport.y / z - margin, right = left + canvasSize.width / z + margin * 2, bottom = top + canvasSize.height / z + margin * 2; return activeScope.value.nodes.filter(node => selectedNodes.has(node.uuid) || node.position.x + node.size.width >= left && node.position.x <= right && node.position.y + node.size.height >= top && node.position.y <= bottom) })
const visibleNodeIds = computed(() => { void graph.value; return new Set(visibleNodes.value.map(node => node.uuid)) })
const visibleEdges = computed(() => { void graph.value; return activeScope.value.edges.filter(edge => visibleNodeIds.value.has(edge.from.nodeUuid) || visibleNodeIds.value.has(edge.to.nodeUuid)) })
const activeNodeIndex = computed(() => { void graph.value; return new Map(activeScope.value.nodes.map(node => [node.uuid,node])) })
const connectedInputPins = computed(() => { void graph.value; return new Set(activeScope.value.edges.map(edge => edge.to.pinUuid)) })
const lowDetail = computed(() => { void graph.value; return useLowDetailGraph(activeScope.value.nodes.length, activeScope.value.viewport.zoom) })
const minimapBounds = computed(() => { void graph.value; const nodes=activeScope.value.nodes;if(!nodes.length)return{minX:0,minY:0,width:1,height:1};let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const node of nodes){const size=graphNodeLayoutSize(node);minX=Math.min(minX,node.position.x);minY=Math.min(minY,node.position.y);maxX=Math.max(maxX,node.position.x+size.width);maxY=Math.max(maxY,node.position.y+size.height)}return{minX,minY,width:Math.max(1,maxX-minX),height:Math.max(1,maxY-minY)} })
const miniViewport = computed(() => { void graph.value; const bounds=minimapBounds.value,viewport=activeScope.value.viewport,worldX=-viewport.x/viewport.zoom,worldY=-viewport.y/viewport.zoom,worldWidth=canvasSize.width/viewport.zoom,worldHeight=canvasSize.height/viewport.zoom,width=Math.min(184,Math.max(4,worldWidth/bounds.width*184)),height=Math.min(94,Math.max(4,worldHeight/bounds.height*94)),x=Math.min(192-width,Math.max(8,8+(worldX-bounds.minX)/bounds.width*184)),y=Math.min(112-height,Math.max(18,18+(worldY-bounds.minY)/bounds.height*94));return{x,y,width,height} })
const liveNodeValueMap=computed(()=>{void graphDebugState.revision;const result=new Map<string,Array<[string,string]>>();for(const entry of graphDebugState.trace){if(entry.graphUuid!==graph.value.uuid||!entry.nodeUuid||result.has(entry.nodeUuid))continue;result.set(entry.nodeUuid,Object.entries(entry.values).slice(0,6).map(([name,value])=>[name,typeof value==='string'?value.slice(0,80):JSON.stringify(value)?.slice(0,80)??String(value)]))}return result})

function snapshot(): string { return serializeGraphDocument(graph.value) }
function compileNow(){if(compileTimer!==undefined){window.clearTimeout(compileTimer);compileTimer=undefined}compileResult.value=compileGraph(graph.value)}
function scheduleCompile(delay=55){if(compileTimer!==undefined)window.clearTimeout(compileTimer);compileTimer=window.setTimeout(compileNow,delay)}
function recordHistory() { if (restoring.value) return; const value = snapshot(); if (history.value[historyIndex.value] === value) return; history.value = history.value.slice(0, historyIndex.value + 1); history.value.push(value); if (history.value.length > 100) history.value.shift(); historyIndex.value = history.value.length - 1 }
function markDirty() { dirty.value = true; triggerRef(graph); scheduleCompile(); recordHistory() }
function markDirtyLive() { dirty.value = true; triggerRef(graph); scheduleCompile(140) }
function queueVisual(update: () => void) { queuedVisualUpdate = update; if (visualFrame) return; visualFrame = requestAnimationFrame(() => { visualFrame = 0; const action = queuedVisualUpdate; queuedVisualUpdate = null; action?.(); triggerRef(graph) }) }
function flushVisualQueue() { if (visualFrame) cancelAnimationFrame(visualFrame); visualFrame = 0; const action = queuedVisualUpdate; queuedVisualUpdate = null; action?.(); triggerRef(graph) }
function commitViewportHistory() { dirty.value = true; recordHistory() }
function scheduleViewportHistory(){if(viewportHistoryTimer!==undefined)window.clearTimeout(viewportHistoryTimer);viewportHistoryTimer=window.setTimeout(()=>{viewportHistoryTimer=undefined;commitViewportHistory()},180)}
function restore(source: string) { restoring.value = true; graph.value = parseGraphDocument(source); if (activeScopeUuid.value !== 'main' && !graph.value.routines.some(item => item.uuid === activeScopeUuid.value)) activeScopeUuid.value = 'main'; selectedNodes.clear(); pendingWire.value = null; compileNow(); nextTick(() => { restoring.value = false }) }
function undo() { if (!canUndo.value) return; historyIndex.value--; restore(history.value[historyIndex.value]); dirty.value = true }
function redo() { if (!canRedo.value) return; historyIndex.value++; restore(history.value[historyIndex.value]); dirty.value = true }

