function selectNode(event: PointerEvent, node: GraphNode) { if (event.button !== 0) return; if (!event.ctrlKey && !event.metaKey && !event.shiftKey) selectedNodes.clear(); if ((event.ctrlKey || event.metaKey) && selectedNodes.has(node.uuid)) selectedNodes.delete(node.uuid); else selectedNodes.add(node.uuid) }
