function applyViewport(viewport:ReturnType<typeof focalGraphZoom>){const scope=activeScope.value;if(Math.abs(viewport.zoom-scope.viewport.zoom)<.0001&&Math.abs(viewport.x-scope.viewport.x)<.01&&Math.abs(viewport.y-scope.viewport.y)<.01)return false;scope.viewport=viewport;dirty.value=true;triggerRef(graph);return true}
