function frameAll(record=true){const scope=activeScope.value;let viewport;if(!scope.nodes.length)viewport={x:80,y:80,zoom:1};else{let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const node of scope.nodes){const size=graphNodeLayoutSize(node);minX=Math.min(minX,node.position.x);minY=Math.min(minY,node.position.y);maxX=Math.max(maxX,node.position.x+size.width);maxY=Math.max(maxY,node.position.y+size.height)}const width=Math.max(1,maxX-minX),height=Math.max(1,maxY-minY),zoom=Math.min(1.2,Math.max(.1,Math.min((canvasSize.width-100)/width,(canvasSize.height-100)/height)));viewport={zoom,x:(canvasSize.width-width*zoom)/2-minX*zoom,y:(canvasSize.height-height*zoom)/2-minY*zoom}}const changed=applyViewport(viewport);if(changed&&record)commitViewportHistory()}

function pinClicked(node:GraphNode,pin:GraphPin){if(pin.direction==='output'){pendingWire.value={node,pin};return}const pending=pendingWire.value;if(!pending||pending.pin.kind!==pin.kind)return;if(pin.kind==='data'&&pending.pin.valueType!==pin.valueType&&pending.pin.valueType!=='Data'&&pin.valueType!=='Data'){addEditorLog(t('graphTypeMismatch',{source:pending.pin.valueType??'',target:pin.valueType??''}),'Script','warning');return}activeScope.value.edges=activeScope.value.edges.filter(edge=>edge.to.pinUuid!==pin.uuid);activeScope.value.edges.push({uuid:graphUuid(),from:{nodeUuid:pending.node.uuid,pinUuid:pending.pin.uuid},to:{nodeUuid:node.uuid,pinUuid:pin.uuid}});pendingWire.value=null;markDirty()}
function startWire(event:PointerEvent,node:GraphNode,pin:GraphPin){if(pin.direction!=='output')return;pendingWire.value={node,pin};pointerMove(event)}
function finishWire(node:GraphNode,pin:GraphPin){if(pin.direction==='input'&&pendingWire.value)pinClicked(node,pin)}
function compatiblePin(pin:GraphPin){const pending=pendingWire.value;if(!pending||pin.direction!=='input'||pending.pin.kind!==pin.kind)return false;return pin.kind==='execution'||pending.pin.valueType===pin.valueType||pending.pin.valueType==='Data'||pin.valueType==='Data'}
function pinConnected(pin:GraphPin){return connectedInputPins.value.has(pin.uuid)}
function pinPoint(node:GraphNode,pin:GraphPin){const index=node.pins.indexOf(pin);return{x:node.position.x+(pin.direction==='output'?node.size.width:0),y:node.position.y+58+index*26}}
function edgePath(edge:GraphEdge){const fromNode=activeNodeIndex.value.get(edge.from.nodeUuid),toNode=activeNodeIndex.value.get(edge.to.nodeUuid),fromPin=fromNode?.pins.find(p=>p.uuid===edge.from.pinUuid),toPin=toNode?.pins.find(p=>p.uuid===edge.to.pinUuid);if(!fromNode||!toNode||!fromPin||!toPin)return'';const a=pinPoint(fromNode,fromPin),b=pinPoint(toNode,toPin),bend=Math.max(45,Math.abs(b.x-a.x)*.45);return`M ${a.x} ${a.y} C ${a.x+bend} ${a.y}, ${b.x-bend} ${b.y}, ${b.x} ${b.y}`}
function edgeKind(edge:GraphEdge){const node=activeNodeIndex.value.get(edge.from.nodeUuid),pin=node?.pins.find(p=>p.uuid===edge.from.pinUuid);return pin?.kind==='execution'?'execution':pin?.valueType?.toLowerCase()??'data'}
const pendingPath=computed(()=>{const pending=pendingWire.value,pointer=pointerGraph.value;if(!pending||!pointer)return'';const a=pinPoint(pending.node,pending.pin),bend=Math.max(45,Math.abs(pointer.x-a.x)*.45);return`M ${a.x} ${a.y} C ${a.x+bend} ${a.y}, ${pointer.x-bend} ${pointer.y}, ${pointer.x} ${pointer.y}`})

function duplicateSelected(){const scope=activeScope.value,originals=scope.nodes.filter(n=>selectedNodes.has(n.uuid)),map=new Map<string,string>(),pinMap=new Map<string,string>(),placed=[...scope.nodes];const copies=originals.map(node=>{const copy=JSON.parse(JSON.stringify(node)) as GraphNode;copy.uuid=graphUuid();map.set(node.uuid,copy.uuid);copy.position=availableGraphPosition(placed,{x:copy.position.x+32,y:copy.position.y+32},graphNodeLayoutSize(copy));placed.push(copy);for(const pin of copy.pins){const old=pin.uuid;pin.uuid=graphUuid();pinMap.set(old,pin.uuid)}return copy});const edges=scope.edges.filter(edge=>map.has(edge.from.nodeUuid)&&map.has(edge.to.nodeUuid)).map(edge=>({uuid:graphUuid(),from:{nodeUuid:map.get(edge.from.nodeUuid)!,pinUuid:pinMap.get(edge.from.pinUuid)!},to:{nodeUuid:map.get(edge.to.nodeUuid)!,pinUuid:pinMap.get(edge.to.pinUuid)!}}));scope.nodes.push(...copies);scope.edges.push(...edges);selectedNodes.clear();for(const copy of copies)selectedNodes.add(copy.uuid);markDirty()}
function deleteSelected(){if(!selectedNodes.size)return;const scope=activeScope.value;scope.nodes=scope.nodes.filter(node=>!selectedNodes.has(node.uuid));scope.edges=scope.edges.filter(edge=>!selectedNodes.has(edge.from.nodeUuid)&&!selectedNodes.has(edge.to.nodeUuid));graph.value.debug.breakpoints=graph.value.debug.breakpoints.filter(point=>!selectedNodes.has(point.nodeUuid));selectedNodes.clear();markDirty()}
